def ndcg(grades,ideal,k):
    import math
    if k<=0:raise ValueError('k')
    def dcg(xs):return sum((2**r-1)/math.log2(i+2) for i,r in enumerate(xs[:k]))
    best=dcg(sorted(ideal,reverse=True))
    return dcg(grades)/best if best else 0

